<div class="row g-4 lease-vs-buy-car-calculator-rebuilt"><div class="col-lg-12"><div class="calculator-card"><div class="calculator-body"><div class="row g-3"><div class="col-md-6"><label class="form-label-custom">Vehicle Price ($)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="lv-price" class="form-control form-control-lg" value="35000" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Down Payment ($)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="lv-down" class="form-control form-control-lg" value="5000" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Lease Rate ($/mo)</label><div class="input-group"><span class="input-group-text bg-light fw-bold">$</span><input type="number" id="lv-lrate" class="form-control form-control-lg" value="350" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Lease Term (mo)</label><div class="input-group"><input type="number" id="lv-lterm" class="form-control form-control-lg" value="36" min="0"></div></div><div class="col-md-6"><label class="form-label-custom">Loan Rate (%)</label><div class="input-group"><input type="number" id="lv-brate" class="form-control form-control-lg" value="5.5" min="0"><span class="input-group-text bg-light fw-bold">%</span></div></div><div class="col-md-6"><label class="form-label-custom">Loan Term (mo)</label><div class="input-group"><input type="number" id="lv-bterm" class="form-control form-control-lg" value="60" min="0"></div></div></div></div></div></div><div class="col-lg-12"><div class="output-card-themed" style="--tool-hue:200;--tool-color:#0ea5e9;--tool-bg:rgba(0,0,0,.02);"><div class="output-hero"><span class="output-hero-label">Lease vs Buy Car Calculator</span><div class="output-hero-value" id="lease-val">—</div><span class="output-hero-unit" id="lease-st">—</span></div><div class="row g-3 mt-3"><div class="col-md-3"><div class="stat-card" style="border-color:#0ea5e9;background:rgba(0,0,0,.02);"><span class="stat-card-label">LEASE COST</span><span class="stat-card-value" style="color:#0ea5e9" id="lv-lcost">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#3b82f6;background:rgba(0,0,0,.02);"><span class="stat-card-label">BUY COST</span><span class="stat-card-value" style="color:#3b82f6" id="lv-bcost">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#22c55e;background:rgba(0,0,0,.02);"><span class="stat-card-label">SAVINGS</span><span class="stat-card-value" style="color:#22c55e" id="lv-save">—</span></div></div><div class="col-md-3"><div class="stat-card" style="border-color:#a855f7;background:rgba(0,0,0,.02);"><span class="stat-card-label">BETTER OPTION</span><span class="stat-card-value" style="color:#a855f7" id="lv-winner">—</span></div></div></div><div class="mt-4" id="lease-ins"></div><div class="row g-2 mt-4"><div class="col-md-4"><button class="btn d-block mx-auto btn-dark py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="lease-cp"><i class="fas fa-copy me-2"></i>Copy Summary</button></div><div class="col-md-4"><button class="btn d-block mx-auto btn-outline-dark py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="lease-rs"><i class="fas fa-rotate-left me-2"></i>Reset</button></div><div class="col-md-4"><button class="btn d-block mx-auto btn-outline-primary py-3 px-4 fw-bold rounded-pill shadow-sm w-100" id="lease-cb"><i class="fas fa-calculator me-2"></i>Calculate</button></div></div></div></div></div>
<script>document.addEventListener("DOMContentLoaded",function(){const $=id=>document.getElementById(id);function fmt(v){return"$"+Math.round(v).toLocaleString();}function calc(){const p=parseFloat($("lv-price").value)||0,dn=parseFloat($("lv-down").value)||0,lr=parseFloat($("lv-lrate").value)||0,lt=parseFloat($("lv-lterm").value)||1,br=(parseFloat($("lv-brate").value)||0)/100/12,bt=parseFloat($("lv-bterm").value)||1;const lc=dn+lr*lt;const loan=p-dn;const mp=br>0?loan*(br*Math.pow(1+br,bt))/(Math.pow(1+br,bt)-1):loan/bt;const bc=dn+mp*bt;const save=Math.abs(lc-bc);const winner=lc<bc?"LEASE":"BUY";$("lease-val").textContent=fmt(Math.min(lc,bc));$("lv-lcost").textContent=fmt(lc);$("lv-bcost").textContent=fmt(bc);$("lv-save").textContent=fmt(save);$("lv-winner").textContent=winner;$("lease-st").textContent=winner+" WINS";$("lease-st").style.color="#22c55e";let ins=[];ins.push("Lease total: <strong>"+fmt(lc)+"</strong>. Buy total: <strong>"+fmt(bc)+"</strong>.");ins.push("<strong>"+winner+"</strong> saves <strong>"+fmt(save)+"</strong> over the period.");$("lease-ins").innerHTML='<h6 class="fw-bold mb-2"><i class="fas fa-lightbulb me-2 text-warning"></i>Analysis</h6><ul class="list-unstyled mb-0 small">'+ins.map(x=>'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>'+x+'</li>').join("")+'</ul>';}['lv-price','lv-down','lv-lrate','lv-lterm','lv-brate','lv-bterm'].forEach(id=>$(id).addEventListener("input",calc));$("lease-cb").addEventListener("click",calc);$("lease-cp").addEventListener("click",function(){navigator.clipboard.writeText("Lease vs Buy Car Calculator: "+$("lease-val").textContent).then(()=>{const o=this.innerHTML;this.innerHTML='<i class="fas fa-check me-2"></i>Copied!';setTimeout(()=>this.innerHTML=o,2e3);});});$("lease-rs").addEventListener("click",()=>{$("lv-price").value=35000;$("lv-down").value=5000;$("lv-lrate").value=350;$("lv-lterm").value=36;$("lv-brate").value=5.5;$("lv-bterm").value=60;calc();});calc();});</script>
<style>.lease-vs-buy-car-calculator-rebuilt .calculator-card{background:#fff;border:1px solid #e5e7eb;border-radius:20px;padding:2rem;box-shadow:0 4px 24px rgba(0,0,0,.04)}.lease-vs-buy-car-calculator-rebuilt .calculator-header{display:flex;align-items:center;gap:1.25rem;margin-bottom:2rem}.lease-vs-buy-car-calculator-rebuilt .calculator-header h4{margin:0;font-weight:700;font-size:1.1rem;color:#1e293b}.lease-vs-buy-car-calculator-rebuilt .calculator-header p{margin:0;font-size:.85rem;color:#64748b}.lease-vs-buy-car-calculator-rebuilt .tool-icon-circle{width:56px;height:56px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.4rem;flex-shrink:0}.lease-vs-buy-car-calculator-rebuilt .form-label-custom{font-size:.75rem;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:.8px;margin-bottom:.4rem;display:block}</style>